function ActivityMournUtils.IsMournPassAll()
	local dojo = ActivityMournUtils.GetMournMgr():GetHomeDojo()
	local maxTowerId = dojo:GetMaxPassTowerId()
	if maxTowerId == 0 then
		return false
	else
		local vo = dojo:GetSchConfig()
		if not vo then
			return false
		end
		
		local questVo = QuestConfMgr:GetInstance():GetQuestVoById(maxTowerId)
		if not questVo then
			return false
		end
		return checkNumber(questVo.storey) == checkNumber(vo.layers)
	end
	return false
end

function ActivityMournUtils.IsPallAllQuest()
	local curId = ActivityMournUtils.GetCurPassTowerId()
	if curId <= 0 then
		return false
	end
	
	local id = QuestConfMgr:GetInstance():GetNextNightCatTowerQuestId(curId)
	if checkNumber(id) == 0 then
		return true
	end
	return false
end

