function ActivityMournUtils.IsUnLockPlot(plotId)
	plotId = checkNumber(plotId)
	local dojo = ActivityMournUtils.GetMournMgr():GetHomeDojo()
	local curPlotId = dojo:GetNowQuestId()
	return curPlotId >= plotId
end

