function ActivityMournUtils.IsUnLockChapter(chapterId)
	chapterId = checkNumber(chapterId)
	if chapterId == 0 then
		return true
	end
	
	local lastPlotId = ActivityMournUtils.GetMournMgr():GetLastPlotId(chapterId)
	return ActivityMournUtils.IsUnLockPlot(lastPlotId)
end

