function ActivityMournUtils.GetCurQuestIndex()
	local index = 1
	local nowQuestId = ActivityMournUtils.GetNowQuestId()
	if nowQuestId == 0 then
		return index
	end
	local vo =  CfUtils.GetCfVo(AutoIds.IdSetting6611, "MournPlotVo", nowQuestId)--暗夜猫剧情
	if isNotNull(vo) then
		local chapterInfo = ActivityMournUtils.GetChapterInfo()
		for i, v in pairs(chapterInfo) do
			if v.chapterId == vo.chapter then
				local isUnLock = ActivityMournUtils.IsUnLockChapter(vo.chapter)
				if isUnLock and i ~= table.count(chapterInfo) then
					index = i + 1
				else
					index = i
				end
				break
			end
		end
	end
	return index
end

function ActivityMournUtils.GetEquipBuffAddPower()
	local addPower = 0
	local equipBuff = ActivityMournUtils.GetEquipBuffIds()
	for i, v in pairs(equipBuff) do
		local level = ActivityMournUtils.GetBuffLevel(v)
		local effectVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(v..level)
		if effectVo then
			addPower = addPower + checkInt(effectVo.combatValue1)
		end
	end
	return addPower
end

function ActivityMournUtils.IsActivityEnd(showTips)
	local dojo = ActivityMournUtils.GetMournMgr():GetHomeDojo()
	local curTime = GameUtils.GetServerTime() or os.time()
	local isEnd = curTime > checkInt(dojo.endTime)
	if isEnd and checkBool(showTips) then
		GameUtils.Toast(localize('活动已结束'))
	end
	return isEnd
end

